<template>
  <div class="detail-page page-enter">
    <div v-if="loading" class="detail-loading" aria-busy="true"><div></div><span>正在打开这个家……</span></div>
    <div v-else-if="!house" class="detail-error"><span class="jade-eyebrow">先别着急</span><h1>暂时没能打开这套房源。</h1><p>{{ error || '房源可能已下架，请看看其他选择。' }}</p><div><button class="jade-button" @click="load">重新加载 <ArrowIcon /></button><RouterLink class="jade-link" to="/houses">返回房源列表 <ArrowIcon /></RouterLink></div></div>
    <template v-else>
      <div class="detail-container"><nav class="detail-breadcrumb" aria-label="当前位置"><RouterLink to="/">首页</RouterLink><span>/</span><RouterLink :to="{ path:'/houses', query:{ city:house.city } }">{{ house.city }}找房</RouterLink><span>/</span><span>{{ house.district }} · 房源详情</span><button @click="share">{{ shareMessage || '分享这个家 ↗' }}</button></nav>
      <div class="detail-overview"><div class="detail-gallery"><div class="detail-main-photo"><Transition name="gallery-fade"><img :key="currentImg" :src="images[currentImg]" :alt="`${house.title}，第${currentImg + 1}张照片`" @error="imageError"></Transition><button v-if="images.length > 1" class="gallery-arrow prev" :disabled="currentImg === 0" aria-label="上一张照片" @click="currentImg--">‹</button><button v-if="images.length > 1" class="gallery-arrow next" :disabled="currentImg === images.length - 1" aria-label="下一张照片" @click="currentImg++">›</button><span class="gallery-count">{{ currentImg + 1 }} / {{ images.length }}</span></div><div class="detail-thumbnails" v-if="images.length > 1"><button v-for="(image, i) in images" :key="image + i" :class="{ selected: i === currentImg }" :aria-label="`查看第${i + 1}张照片`" :aria-pressed="i === currentImg" @click="currentImg = i"><img :src="image" alt="" @error="imageError"></button></div></div>
      <aside class="detail-summary"><span class="jade-eyebrow">{{ house.city }} · {{ house.district }}</span><h1>{{ house.title }}</h1><p class="detail-rent">¥ {{ Number(house.price || 0).toLocaleString('zh-CN') }}<small> / 月</small></p><div class="detail-key-info"><span><b>{{ house.bedrooms }}室{{ house.livingRooms }}厅</b><small>户型</small></span><span><b>{{ house.area }}㎡</b><small>建筑面积</small></span><span><b>{{ house.orientation || '待了解' }}</b><small>朝向</small></span></div><p class="summary-address">{{ house.address || house.city + house.district }}</p><p v-if="house.subwayStationName" class="summary-transit">{{ house.subwayLineName }} · {{ house.subwayStationName }}站 <span v-if="house.distanceToSubway"> / 约 {{ house.distanceToSubway }}m</span></p><div class="summary-owner"><span>{{ (house.landlordName || '房东').slice(0,1) }}</span><div>{{ house.landlordName || '房东' }}<small>房源发布者</small></div></div><button class="jade-button contact-button" :disabled="contacting || user.userId===house.landlordId" @click="contactLandlord">{{ contacting?'正在打开聊天…':user.userId===house.landlordId?'这是你发布的房源':'私信房东' }} <ArrowIcon /></button><p v-if="contactError" role="alert" class="favorite-message">{{ contactError }}</p><button v-if="house.contactPhone" class="jade-button contact-button phone-button" @click="showPhone = !showPhone">{{ showPhone ? house.contactPhone : '查看联系电话' }} <ArrowIcon /></button><RouterLink v-else class="jade-button contact-button" to="/app/chat">向小易了解房源 <ArrowIcon /></RouterLink><button class="detail-favorite" :class="{ selected: favorited }" :disabled="favoriteLoading" @click="toggleFavorite">{{ favoriteLoading ? '正在保存…' : favorited ? '♥ 已收藏这个家' : '♡ 收藏这个家' }}</button><p v-if="favoriteMessage" class="favorite-message" role="status">{{ favoriteMessage }}</p><small class="summary-id">房源编号 YZB{{ String(house.id).padStart(6,'0') }}<span v-if="house.viewCount"> · {{ house.viewCount }} 次浏览</span></small></aside></div>
      <TrustPanel :house-id="house.id"/><ContentComposer kind="review" :house-id="house.id" :landlord-id="house.landlordId"/><div class="detail-body"><div class="detail-article"><section><span class="jade-eyebrow">认真了解，再做决定</span><h2>关于这个家</h2><div class="detail-facts"><div><span>楼层</span><b>{{ house.floorInfo || '待了解' }}</b></div><div><span>装修</span><b>{{ house.decoration || '待了解' }}</b></div><div><span>卫生间</span><b>{{ house.bathrooms ? house.bathrooms + '卫' : '待了解' }}</b></div><div v-if="house.createdAt"><span>发布时间</span><b>{{ String(house.createdAt).slice(0,10) }}</b></div></div><p class="detail-description">{{ house.description || '房源的更多细节，可以向顾问进一步了解。' }}</p></section><section v-if="facilities.length"><h2>生活的日常配套</h2><div class="detail-facilities"><span v-for="f in facilities" :key="f"><span aria-hidden="true">✓</span>{{ f }}</span></div></section><section><h2>位置与周边</h2><p class="map-address">{{ house.city }} {{ house.district }} {{ house.address }}</p><div ref="mapElement" class="detail-map" aria-label="房源所在城市地图"></div><p class="map-note">{{ house.latitude && house.longitude ? (house.description?.includes('仿真') ? '地图为演示房源所在区域的参考位置，不代表实际出租房屋。' : '地图位置由发布者标记，请在看房前核实。') : '当前为所在城市参考位置，具体地址请以房源信息为准。' }}</p></section><section v-if="reviews.length"><h2>租客的居住感受</h2><article v-for="review in reviews.slice(0,4)" :key="review.id" class="detail-review"><span>{{ '★'.repeat(Math.min(5,Math.max(0,Math.round(review.score || 0)))) }}</span><p>{{ review.content }}</p></article></section></div><aside class="detail-life-note"><img src="/images/moving-day.png" alt="慢慢整理喜欢的生活" loading="lazy"><h3>房间之外，<br>也想想自己的日常。</h3><p>通勤多久？周末去哪里？<br>把生活的期待，也放进找房清单。</p><RouterLink class="jade-link" to="/app/chat">和顾问聊聊 <ArrowIcon /></RouterLink><RouterLink class="jade-link" to="/app/tools?tool=contract">签字前，看看合同 <ArrowIcon /></RouterLink></aside></div>
