const fallback = '/house-images/uns_1600210492486-724fe5c67fb0.jpg'
const parseList = value => { if(Array.isArray(value)) return value; try { const parsed=JSON.parse(value); return Array.isArray(parsed)?parsed:[] } catch { return typeof value === 'string' ? value.split(/[,，]/).map(s=>s.trim()).filter(Boolean) : [] } }
const images = computed(() => { const values = parseList(house.value?.images).filter(v=>typeof v==='string' && v.trim()); if (!values.length && house.value?.coverImage) values.push(house.value.coverImage); return values.length ? values : [fallback] })
const facilities = computed(() => parseList(house.value?.facilities))
let map, alive = true
const centers={'杭州':[30.27,120.15],'深圳':[22.54,114.06],'北京':[39.92,116.40],'上海':[31.23,121.47],'广州':[23.13,113.26],'成都':[30.57,104.07],'武汉':[30.59,114.30],'南京':[32.06,118.80],'苏州':[31.30,120.58],'长沙':[28.20,113.00],'重庆':[29.56,106.55],'西安':[34.26,108.94],'天津':[39.13,117.20],'青岛':[36.07,120.38],'郑州':[34.75,113.62],'佛山':[23.02,113.12],'东莞':[23.02,113.75],'合肥':[31.82,117.23],'厦门':[24.48,118.09],'宁波':[29.87,121.55]}
