async function loadRelated(){const current=house.value;try{const r=await houseApi.list({status:'APPROVED',city:current.city,bedrooms:current.bedrooms,page:1,size:4});if(alive)similar.value=(Array.isArray(r.data)?r.data:r.data?.list || []).filter(h=>h.id!==current.id).slice(0,3)}catch{}if(current.landlordId)try{const r=await reviewApi.list(current.landlordId);if(alive)reviews.value=r.data?.reviews || []}catch{} }
async function contactLandlord(){if(!user.isLogin){auth.open(route.fullPath);return}if(contacting.value)return;contacting.value=true;contactError.value='';try{const r=await messagesApi.start(house.value.id);await router.push({path:'/app/messages',query:{conversation:r.data.id}})}catch(e){contactError.value=e.message||'无法打开聊天，请重试'}finally{contacting.value=false}}
async function toggleFavorite(){if(!user.isLogin){auth.open(route.fullPath);return}favoriteLoading.value=true;favoriteMessage.value='';try{favorited.value?await favoriteApi.remove(house.value.id):await favoriteApi.add(house.value.id);favorited.value=!favorited.value;favoriteMessage.value=favorited.value?'已保存到个人中心的收藏。':'已取消收藏。'}catch(e){favoriteMessage.value=e.message || '保存失败，请稍后重试。'}finally{favoriteLoading.value=false} }
async function share(){try{await navigator.clipboard.writeText(window.location.href);shareMessage.value='链接已复制'}catch{shareMessage.value='复制地址栏链接，即可分享'}}
function imageError(event){if(!event.target.src.endsWith(fallback))event.target.src=fallback}
function initMap(){if(!mapElement.value||!house.value||!alive)return;map?.remove();const center=centers[house.value.city] || centers['杭州'];const precise=house.value.latitude&&house.value.longitude;const position=precise?[house.value.latitude,house.value.longitude]:center;map=L.map(mapElement.value,{scrollWheelZoom:true}).setView(position,precise?16:12);L.tileLayer('https://webrd0{s}.is.autonavi.com/appmaptile?lang=zh_cn&size=1&scale=1&style=8&x={x}&y={y}&z={z}',{subdomains:['1','2','3','4'],maxZoom:18,attribution:'高德地图'}).addTo(map);L.circleMarker(position,{radius:8,color:'#168b78',fillColor:'#168b78',fillOpacity:.5}).addTo(map)}
